using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// --- Tool instances ---
var notebook = new Notebook();
var webSearch = new WebSearcher();

// --- Build IChatClient with automatic function invocation ---
IChatClient chatClient = new ChatClientBuilder(
        new OpenAIClient(apiKey).GetChatClient(model).AsIChatClient())
    .UseFunctionInvocation()
    .Build();

// --- Define tools ---
AIFunction[] tools =
[
    AIFunctionFactory.Create(webSearch.SearchAsync),
    AIFunctionFactory.Create(notebook.SaveNote),
    AIFunctionFactory.Create(notebook.GetNotes),
];

// --- Create the agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Your job is to research a topic the user provides
        by searching the web for relevant information.

        Follow this process:
        1. Break the topic into 2-3 specific search queries.
        2. Search the web for each query.
        3. Save important findings as notes (include the source URL).
        4. After gathering enough information, review your notes and provide a
           comprehensive summary with key findings and sources.

        Always save your findings before summarizing. Be thorough but concise.
        """,
    name: "ResearchAgent",
    description: "An AI agent that researches topics using web search and note-taking.");

// --- Run the agent ---
var topic = args.Length > 0
    ? string.Join(' ', args)
    : PromptForTopic();

Console.WriteLine($"\n🔍 Researching: {topic}\n");

var session = new ChatClientAgentSession();
var options = new ChatClientAgentRunOptions(new ChatOptions { Tools = tools });

var response = await agent.RunAsync(
    $"Research the following topic and provide a summary: {topic}",
    session,
    options);

Console.WriteLine("\n══════════════════════════════════════════");
Console.WriteLine("📋 RESEARCH COMPLETE");
Console.WriteLine("══════════════════════════════════════════\n");

foreach (var msg in response.Messages)
{
    if (msg.Role == ChatRole.Assistant && !string.IsNullOrWhiteSpace(msg.Text))
        Console.WriteLine(msg.Text);
}

if (notebook.Count > 0)
{
    Console.WriteLine($"\n📝 {notebook.Count} note(s) saved during research.");
}

return;

static string PromptForTopic()
{
    Console.Write("Enter a research topic: ");
    var input = Console.ReadLine()?.Trim();
    return string.IsNullOrEmpty(input)
        ? "Recent advances in quantum computing 2026"
        : input;
}

