/// <summary>Searches the web using the Bing search page and extracts results.</summary>
sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
        },
        Timeout = TimeSpan.FromSeconds(15)
    };

    [Description("Searches the web for a query and returns a list of result snippets with URLs.")]
    public async Task<string> SearchAsync(
        [Description("The search query string")] string query,
        CancellationToken cancellationToken = default)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            var encoded = Uri.EscapeDataString(query);
            var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
            var html = await Http.GetStringAsync(url, cancellationToken);
            var results = ParseDuckDuckGoLite(html);

            if (results.Count == 0)
                return $"No results found for \"{query}\".";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for \"{query}\":");
            foreach (var (title, link, snippet) in results.Take(5))
            {
                sb.AppendLine($"- [{title}]({link})");
                if (!string.IsNullOrWhiteSpace(snippet))
                    sb.AppendLine($"  {snippet}");
            }
            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for \"{query}\": {ex.Message}";
        }
    }

    private static List<(string Title, string Url, string Snippet)> ParseDuckDuckGoLite(string html)
    {
        var results = new List<(string, string, string)>();

        // Extract result links and snippets from DuckDuckGo Lite HTML
        var lines = html.Split('\n');
        string? currentTitle = null;
        string? currentUrl = null;

        foreach (var line in lines)
        {
            var trimmed = line.Trim();

            // Look for result links: <a rel="nofollow" href="..." class="result-link">Title</a>
            if (trimmed.Contains("result-link", StringComparison.OrdinalIgnoreCase)
                || (trimmed.Contains("rel=\"nofollow\"", StringComparison.OrdinalIgnoreCase)
                    && trimmed.Contains("href=", StringComparison.OrdinalIgnoreCase)
                    && !trimmed.Contains("duckduckgo.com", StringComparison.OrdinalIgnoreCase)))
            {
                var hrefStart = trimmed.IndexOf("href=\"", StringComparison.OrdinalIgnoreCase);
                if (hrefStart >= 0)
                {
                    hrefStart += 6;
                    var hrefEnd = trimmed.IndexOf('"', hrefStart);
                    if (hrefEnd > hrefStart)
                        currentUrl = trimmed[hrefStart..hrefEnd];
                }

                // Extract title from tag content
                var tagClose = trimmed.IndexOf('>');
                var tagEnd = trimmed.LastIndexOf('<');
                if (tagClose >= 0 && tagEnd > tagClose)
                    currentTitle = StripHtml(trimmed[(tagClose + 1)..tagEnd]);
            }

            // Look for snippet text in <td> elements following a result link
            if (currentUrl != null && trimmed.StartsWith("<td", StringComparison.OrdinalIgnoreCase)
                && trimmed.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
            {
                var snippet = StripHtml(trimmed);
                results.Add((currentTitle ?? "Untitled", currentUrl, snippet));
                currentTitle = null;
                currentUrl = null;
            }

            // Also catch when URL is set but we find next result before snippet
            if (currentUrl != null && results.Count < 8
                && trimmed.Contains("result__a", StringComparison.OrdinalIgnoreCase))
            {
                results.Add((currentTitle ?? "Untitled", currentUrl, ""));
                currentTitle = null;
                currentUrl = null;
            }
        }

        // If we captured a URL but never added it
        if (currentUrl != null)
            results.Add((currentTitle ?? "Untitled", currentUrl, ""));

        return results;
    }

    private static string StripHtml(string html)
    {
        var sb = new StringBuilder();
        var inTag = false;
        foreach (var c in html)
        {
            if (c == '<') inTag = true;
            else if (c == '>') inTag = false;
            else if (!inTag) sb.Append(c);
        }
        return System.Net.WebUtility.HtmlDecode(sb.ToString().Trim());
    }
}

/// <summary>A simple in-memory notebook for storing research notes.</summary>
sealed class Notebook
{
    private readonly List<(string Topic, string Content)> _notes = [];

    public int Count => _notes.Count;

    [Description("Saves a research note with a topic label and content. Use this to record important findings.")]
    public string SaveNote(
        [Description("Short label for the note (e.g. 'quantum computing basics')")] string topic,
        [Description("The note content including key facts, quotes, and source URLs")] string content)
    {
        _notes.Add((topic, content));
        Console.WriteLine($"  📝 Note saved: \"{topic}\"");
        return $"Note #{_notes.Count} saved under \"{topic}\".";
    }

    [Description("Retrieves all saved research notes collected so far.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"=== {_notes.Count} Research Note(s) ===");
        for (var i = 0; i < _notes.Count; i++)
        {
            var (topic, content) = _notes[i];
            sb.AppendLine($"\n--- Note #{i + 1}: {topic} ---");
            sb.AppendLine(content);
        }
        return sb.ToString();
    }
}

