88. /// <summary>Searches the web using the Bing search page and extracts results.</summary>
89. sealed class WebSearcher
90. {
91.     private static readonly HttpClient Http = new()
92.     {
93.         DefaultRequestHeaders =
94.         {
95.             { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" }
96.         },
97.         Timeout = TimeSpan.FromSeconds(15)
98.     };
99. 
100.     [Description("Searches the web for a query and returns a list of result snippets with URLs.")]
101.     public async Task<string> SearchAsync(
102.         [Description("The search query string")] string query,
103.         CancellationToken cancellationToken = default)
104.     {
105.         Console.WriteLine($"  🌐 Searching: \"{query}\"");
106. 
107.         try
108.         {
109.             var encoded = Uri.EscapeDataString(query);
110.             var url = $"https://lite.duckduckgo.com/lite/?q={encoded}";
111.             var html = await Http.GetStringAsync(url, cancellationToken);
112.             var results = ParseDuckDuckGoLite(html);
113. 
114.             if (results.Count == 0)
115.                 return $"No results found for \"{query}\".";
116. 
117.             var sb = new StringBuilder();
118.             sb.AppendLine($"Search results for \"{query}\":");
119.             foreach (var (title, link, snippet) in results.Take(5))
120.             {
121.                 sb.AppendLine($"- [{title}]({link})");
122.                 if (!string.IsNullOrWhiteSpace(snippet))
123.                     sb.AppendLine($"  {snippet}");
124.             }
125.             return sb.ToString();
126.         }
127.         catch (Exception ex)
128.         {
129.             return $"Search failed for \"{query}\": {ex.Message}";
130.         }
131.     }
132. 
133.     private static List<(string Title, string Url, string Snippet)> ParseDuckDuckGoLite(string html)
134.     {
135.         var results = new List<(string, string, string)>();
136. 
137.         // Extract result links and snippets from DuckDuckGo Lite HTML
138.         var lines = html.Split('\n');
139.         string? currentTitle = null;
140.         string? currentUrl = null;
141. 
142.         foreach (var line in lines)
143.         {
144.             var trimmed = line.Trim();
145. 
146.             // Look for result links: <a rel="nofollow" href="..." class="result-link">Title</a>
147.             if (trimmed.Contains("result-link", StringComparison.OrdinalIgnoreCase)
148.                 || (trimmed.Contains("rel=\"nofollow\"", StringComparison.OrdinalIgnoreCase)
149.                     && trimmed.Contains("href=", StringComparison.OrdinalIgnoreCase)
150.                     && !trimmed.Contains("duckduckgo.com", StringComparison.OrdinalIgnoreCase)))
151.             {
152.                 var hrefStart = trimmed.IndexOf("href=\"", StringComparison.OrdinalIgnoreCase);
153.                 if (hrefStart >= 0)
154.                 {
155.                     hrefStart += 6;
156.                     var hrefEnd = trimmed.IndexOf('"', hrefStart);
157.                     if (hrefEnd > hrefStart)
158.                         currentUrl = trimmed[hrefStart..hrefEnd];
159.                 }
160. 
161.                 // Extract title from tag content
162.                 var tagClose = trimmed.IndexOf('>');
163.                 var tagEnd = trimmed.LastIndexOf('<');
164.                 if (tagClose >= 0 && tagEnd > tagClose)
165.                     currentTitle = StripHtml(trimmed[(tagClose + 1)..tagEnd]);
166.             }
167. 
168.             // Look for snippet text in <td> elements following a result link
169.             if (currentUrl != null && trimmed.StartsWith("<td", StringComparison.OrdinalIgnoreCase)
170.                 && trimmed.Contains("result-snippet", StringComparison.OrdinalIgnoreCase))
171.             {
172.                 var snippet = StripHtml(trimmed);
173.                 results.Add((currentTitle ?? "Untitled", currentUrl, snippet));
174.                 currentTitle = null;
175.                 currentUrl = null;
176.             }
177. 
178.             // Also catch when URL is set but we find next result before snippet
179.             if (currentUrl != null && results.Count < 8
180.                 && trimmed.Contains("result__a", StringComparison.OrdinalIgnoreCase))
181.             {
182.                 results.Add((currentTitle ?? "Untitled", currentUrl, ""));
183.                 currentTitle = null;
184.                 currentUrl = null;
185.             }
186.         }
187. 
188.         // If we captured a URL but never added it
189.         if (currentUrl != null)
190.             results.Add((currentTitle ?? "Untitled", currentUrl, ""));
191. 
192.         return results;
193.     }
194. 
195.     private static string StripHtml(string html)
196.     {
197.         var sb = new StringBuilder();
198.         var inTag = false;
199.         foreach (var c in html)
200.         {
201.             if (c == '<') inTag = true;
202.             else if (c == '>') inTag = false;
203.             else if (!inTag) sb.Append(c);
204.         }
205.         return System.Net.WebUtility.HtmlDecode(sb.ToString().Trim());
206.     }
207. }
